from pathlib import Path
import pandas as pd
ROOT=Path(__file__).resolve().parents[1]; d=pd.read_csv(ROOT/'data/iqvia_india_q2_2025_public_metrics.csv')
rows=''.join(f'<tr><td>{r.metric}</td><td>{r.segment}</td><td>{r.value:g} {r.unit}</td></tr>' for _,r in d.iterrows())
html=f'''<!doctype html><meta charset="utf-8"><title>Pune India Commercial Analytics Workbench</title><style>body{{font:16px Arial;max-width:1050px;margin:32px auto;color:#172033}}.hero{{background:#172554;color:#fff;padding:30px;border-radius:16px}}.grid{{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}}.card{{background:#ecfeff;padding:18px;border-radius:12px}}table{{border-collapse:collapse;width:100%}}td,th{{padding:9px;border-bottom:1px solid #ddd;text-align:left}}.note{{background:#fff7ed;border-left:4px solid #f97316;padding:14px}}</style><div class="hero"><h1>Pune Office | India Commercial Analytics Workbench</h1><p>Public IQVIA India market evidence + synthetic HCP response modelling</p></div><h2>India market signals</h2><div class="grid"><div class="card"><b>IPM size</b><br>₹61,000 Cr</div><div class="card"><b>IPM growth</b><br>9%</div><div class="card"><b>West growth</b><br>11%</div><div class="card"><b>GLP-1 growth</b><br>145%</div></div><h2>Consulting workflow</h2><ol><li>Use public aggregate evidence to define the business question.</li><li>Validate and document licensed data once approved.</li><li>Segment HCPs/regions and estimate promotion response.</li><li>Simulate allocation scenarios and quantify uncertainty.</li><li>Deliver a PowerPoint-ready recommendation with lineage and limitations.</li></ol><h2>Source metrics</h2><table><tr><th>Metric</th><th>Segment</th><th>Value</th></tr>{rows}</table><p><a href="https://www.iqvia.com/locations/india/library/presentations/indian-pharmaceutical-business-quarterly-insights-q2-2025">IQVIA source: Indian Pharmaceutical Business Quarterly Insights Q2 2025</a></p><div class="note"><b>Governance:</b> The aggregate figures are public IQVIA market evidence. HCP-level records in this portfolio are synthetic. This is not an IQVIA internal tool and does not claim actual revenue impact.</div>'''
(ROOT/'reports/pune_india_workbench.html').write_text(html)
